"""Run-length encoding and decoding."""


def encode(text):
    """Run-length encode ``text``.

    Each run of one repeated character is replaced by its length followed by
    the character. A run of length 1 is written as the character alone.
    ``text`` must not contain the digits 0 to 9.
    """
    if any("0" <= ch <= "9" for ch in text):
        raise ValueError("text must not contain digits")

    if not text:
        return ""

    result = []
    run_char = text[0]
    run_len = 1
    for ch in text[1:]:
        if ch == run_char:
            run_len += 1
        else:
            if run_len > 1:
                result.append(str(run_len))
            result.append(run_char)
            run_char = ch
            run_len = 1
    if run_len > 1:
        result.append(str(run_len))
    result.append(run_char)
    return "".join(result)


def decode(text):
    """Reverse :func:`encode`.

    Raises ``ValueError`` for text that ``encode`` cannot produce: a count of
    0 or 1, a count with a leading zero, or a count with no character after it.
    """
    result = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if "0" <= ch <= "9":
            # A digit starts a count.
            j = i
            while j < n and "0" <= text[j] <= "9":
                j += 1
            count_str = text[i:j]
            # A count must be followed by a character.
            if j >= n:
                raise ValueError("count with no character after it")
            # A count with a leading zero is not produced by encode.
            if len(count_str) > 1 and count_str[0] == "0":
                raise ValueError("count with leading zero")
            count = int(count_str)
            # encode never writes counts of 0 or 1.
            if count <= 1:
                raise ValueError("count of 0 or 1 is not allowed")
            result.append(text[j] * count)
            i = j + 1
        else:
            # A single character (run of length 1).
            result.append(ch)
            i += 1
    return "".join(result)
